ValidationRule.errorConditionFormula:
if (isblank (Lunch_Start__c) && isblank(Lunch_End__c), FALSE,

if (contains(Lunch_Start__c, "AM") && contains (Lunch_End__c, "PM"), FALSE, 

if (contains(Lunch_Start__c, "PM") && contains (Lunch_End__c, "AM"), TRUE, 

if (contains(Lunch_Start__c, "12:") && not(contains (Lunch_End__c, "12:")), FALSE,

if (contains(Lunch_Start__c, "AM") && contains (Lunch_End__c, "AM") && value(substitute(substitute(Lunch_End__c, " AM", NULL), ":", "."))-value(substitute(substitute(Lunch_Start__c, " AM", NULL), ":", "."))>=0, FALSE, 

if (contains(Lunch_Start__c, "PM") && contains (Lunch_End__c, "PM") && value(substitute(substitute(Lunch_End__c, " PM", NULL), ":", "."))-value(substitute(substitute(Lunch_Start__c, " PM", NULL), ":", "."))>=0, FALSE, 

TRUE))))))
